                    ["body"] = "Bazzalan and Jergosh are reported slain. The loss disrupts the Searing Blade in Ragefire Chasm.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 completion; #5729 completion"},
                    ["related"] = {"npc:bazzalan", "npc:jergosh"}
                }
            }
        },
        ["npc:taragaman"] = {
            ["public"] = {
                ["body"] = "Taragaman the Hungerer is a felguard in Ragefire Chasm beneath Orgrimmar. The demon inhabits a cavern complex occupied by troggs and the Searing Blade. The entrance lies in the Cleft of Shadow, placing this underground danger inside the Horde capital.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5761 description", "https://news.blizzard.com/en-gb/article/23156369/wow-classic-city-tour-orgrimmar"},
                ["related"] = {"dungeon:ragefire"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.taragaman_claim"},
                    ["body"] = "Neeru calls Taragaman the Searing Blade's leader and requests the felguard's heart, claiming the deed will please Thrall.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5761 description"},
                    ["related"] = {"npc:neeru-fireblade", "npc:taragaman"}
                },
                {
                    ["requires"] = {"neeru.taragaman_heart"},
                    ["body"] = "Neeru receives Taragaman's heart and promises to report the success to Thrall.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5761 completion"},
                    ["related"] = {"npc:neeru-fireblade", "npc:taragaman"}
                }
            }
        },
        ["npc:stalvan"] = {
            ["public"] = {
                ["body"] = "Stalvan is the subject of an inquiry in Darkshire. The town hall's records offer a starting point for learning more about the name.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 66"},
                ["related"] = {"place:darkshire"},
                ["title"] = "Stalvan"
            },
            ["blocks"] = {
                {
                    ["requires"] = {"stalvan.case_opened"},
                    ["body"] = "Madame Eva fears for her granddaughter Alyssa after a disturbing vision. Her cards show Death, and a trance brings her the name Stalvan. She asks for inquiries at Darkshire's town hall; the name is a lead, without an explanation of the danger.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 66"},
                    ["related"] = {"place:darkshire"}
                },
                {
                    ["requires"] = {"stalvan.registry_identity"},
                    ["body"] = "Clerk Daltry's registry identifies Stalvan Mistmantle and gives Moonbrook Schoolhouse as his last recorded address. Daltry warns that the record is old and asks for an update.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 67"},
                    ["related"] = {"place:moonbrook"}
                },
                {
                    ["requires"] = {"stalvan.moonbrook_confirmed"},
                    ["body"] = "An unsent letter convinces Daltry that Stalvan spent time in Moonbrook. He undertakes to update the town's records.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 68"},
                    ["related"] = {"place:moonbrook"}
                },
                {
                    ["requires"] = {"stalvan.goldshire_lead"},
                    ["body"] = "A second address in Daltry's registry is partly scratched out. It points toward the Lion's Pride Inn in Goldshire, giving the inquiry another place to seek information.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 69"},
                    ["related"] = {}
                },
                {
                    ["requires"] = {"stalvan.messenger_account"},
                    ["body"] = "Innkeeper Farley recalls a messenger who fled the inn in terror during a storm years earlier. The abandoned correspondence includes a letter from Stalvan intended for Stormwind's Canal District; Farley offers it as a lead.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 70"},
                    ["related"] = {}
                },
                {
                    ["requires"] = {"stalvan.massacre_context"},
                    ["body"] = "Caretaker Folsom says his father cleaned the estate after a massacre. With the Flintridge trust exhausted, the remaining family possessions are being packed for auction. He permits a search among them for information.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 72"},
                    ["related"] = {}
                },
                {
                    ["requires"] = {"stalvan.torn_page_found"},
                    ["body"] = "A torn journal page lies among the estate's packed heirlooms, portrait, trophies and books. Its discovery supplies another document for the inquiry.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 74"},
                    ["related"] = {}
                },
                {
                    ["requires"] = {"stalvan.faded_page_search"},
                    ["body"] = "Marshal Haggard remembers parchments left in an upstairs chest when he moved into his home. His failing sight prevents him from examining them easily, and he asks for a faded journal page that may assist the inquiry.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 75"},
                    ["related"] = {}
                },
                {
                    ["requires"] = {"stalvan.smitts_referral"},
                    ["body"] = "Haggard recommends Tavernkeep Smitts of Darkshire's Scarlet Raven Tavern as someone knowledgeable about local history. He asks that Smitts examine the faded page.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 78"},
                    ["related"] = {}
                },
                {
                    ["requires"] = {"stalvan.smitts_recognition"},
                    ["body"] = "On seeing the page, Smitts recognizes the handwriting.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 78"},
                    ["related"] = {}
                },
                {
                    ["requires"] = {"stalvan.guilt_account"},
                    ["body"] = "Smitts recounts investigating the deaths of visiting nobles with Haggard. They had found muddy pages but could not connect the writing to the man in the woods. Smitts now considers the gathered evidence proof of Stalvan's guilt and calls for Commander Ebonlocke to hear it.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 79"},
                    ["related"] = {}
                },
                {
                    ["requires"] = {"stalvan.comparison_order"},
                    ["body"] = "Commander Ebonlocke requests a comparison between the page's handwriting and Stalvan's registry signature. She relies on Daltry's experience with the town records to test her suspicion.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 80"},
                    ["related"] = {}
                },
                {
                    ["requires"] = {"stalvan.handwriting_confirmed"},
                    ["body"] = "Daltry confirms that the page's handwriting matches the registry signatures, supporting Ebonlocke's suspicion.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 80", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 97"},
                    ["related"] = {}
                },
                {
                    ["requires"] = {"stalvan.execution_order"},
                    ["body"] = "Commander Ebonlocke identifies Stalvan Mistmantle as a killer who threatens Darkshire and orders his execution at the cottage north of town. She requests that his family ring be taken to Madame Eva afterward as proof.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 98"},
                    ["related"] = {"place:darkshire"}
                },
                {
                    ["requires"] = {"stalvan.dead"},
                    ["body"] = "Madame Eva's response to the completed assignment confirms Stalvan's death. She welcomes the end of his killings while mourning those who died by his hand.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 98"},
                    ["related"] = {}
                }
            }
        },
        ["place:moonbrook"] = {
            ["public"] = {
                ["body"] = "Moonbrook is a town in southwestern Westfall, where Defias pillagers threaten the countryside. Its roads connect with the Gold Coast Quarry and Jangolode Mine, making the settlement part of the People's Militia's struggle to restore safety to the farms and workings of Westfall.\n\nThe mines beneath a barn preserve another part of the town's history. A tunnel collapse left miners and an Explorers' League party missing; survivors seek badges and union cards that might bring answers to their families. The schoolhouse is another reminder of the community's earlier life.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 13", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 142", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 167", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 168", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 67"},
                ["related"] = {"region:5765737466616c6c", "group:peoples-militia"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"stalvan.registry_identity"},
                    ["body"] = "Darkshire's old registry gives Moonbrook Schoolhouse as Stalvan Mistmantle's last recorded address. Daltry asks for newer information about him.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 67"},
                    ["related"] = {"npc:stalvan"}
                },
                {
                    ["requires"] = {"stalvan.moonbrook_confirmed"},
                    ["body"] = "An unsent letter supplies Daltry with evidence that Stalvan spent time in Moonbrook.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 68"},
                    ["related"] = {"npc:stalvan"}
                }
            }
        },
        ["place:darkshire"] = {
            ["public"] = {
                ["body"] = "Darkshire is a town in Duskwood protected by the Night Watch. After Stormwind withdrew its commissioned guards, Commander Althea Ebonlocke and the watchers took responsibility for defending its people. Undead gather in Tranquil Gardens to the south and at Raven Hill Cemetery, stretching the small force across a troubled region.\n\nCivic work and ordinary hospitality continue beside that defense. The town hall keeps its registry, while the Scarlet Raven Tavern offers meals prepared by Chef Grual. Tavernkeep Smitts is known to Marshal Haggard for his knowledge of local history. Records, provisions and local memory all have a place in the town's daily life.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 56", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 58", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 5", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 67", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 78"},
                ["related"] = {"region:4475736b776f6f64"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"stalvan.case_opened"},
                    ["body"] = "Madame Eva brings the name Stalvan into a local inquiry and directs the search toward the town hall.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 66"},
                    ["related"] = {"npc:stalvan"}
                }
            }
        },
        ["region:4475736b776f6f64"] = {
            ["public"] = {
                ["body"] = "Duskwood is the darkened woodland south of Elwynn Forest. Its people depend on Darkshire's Night Watch after the withdrawal of Stormwind's commissioned guards. Commander Althea Ebonlocke faces undead in Tranquil Gardens and Raven Hill Cemetery with too few watchers to keep every threatened place secure.\n\nWorgen roam the woods and have overrun the Rotting Orchard southwest of Darkshire. Townspeople and their defenders face dangers along the roads and beyond the settled houses, while the Scarlet Raven Tavern remains a place for food and local knowledge. The region's abandoned settlements and troubled graveyards stand close to a community still keeping its records, feeding travelers and defending its homes.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 56", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 58", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 221", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 5", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 67", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 78"},
                ["related"] = {"place:darkshire", "region:456c77796e6e20466f72657374"}
            },
            ["blocks"] = {}
        },
        ["quest:66"] = {
            ["public"] = {
                ["body"] = "The Legend of Stalvan is an inquiry in Darkshire. Madame Eva seeks information, and the town hall offers a place to begin tracing a name. The investigation depends on what its records and witnesses can establish.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 66"},
                ["related"] = {"place:darkshire"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"stalvan.case_opened"},
                    ["body"] = "Madame Eva fears for her granddaughter Alyssa after a disturbing vision. Her cards show Death, and a trance brings her the name Stalvan. She asks for inquiries at Darkshire's town hall; the name is a lead, without an explanation of the danger.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 66"},
                    ["related"] = {"place:darkshire"}
                }
            }
        },
        ["quest:67"] = {
