-- Oct 29 bounded review: the royal rescue and the Scarlet Bastion's commander.
-- These stages disclose their own text, never an assumed predecessor's dialogue.
do
    local V = "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt"
    local function Rule(body, source, related, blocks, title)
        return {public={body=body,sources={source},related=related or {},title=title},blocks=blocks or {}}
    end
    local family = {requires={"moira.family"},
        body="Moira says her life and that of her unborn child have been ruined. She declares that the child will inherit Ironforge as a Dark Iron dwarf. Her words challenge the account on which the rescue was ordered.",
        sources={V .. " #4004 and #4363 descriptions"},related={"npc:moira","npc:dagran","npc:magni"}}
    local husband = {requires={"moira.husband"},
        body="Moira calls the slain Thaurissan her husband and says her child will be born without a father.",
        sources={V .. " #4004 description"},related={"npc:moira","npc:dagran"}}
    local magniReply = {requires={"moira.magni_reply"},
        body="The message leaves Magni visibly upset. He says that Thaurissan has won even in death, dismisses the messenger with a reward and slumps into his throne to consider the news.",
        sources={V .. " #4363 completion"},related={"npc:magni"}}
    local thrallReply = {requires={"moira.thrall_reply"},
        body="Thrall is taken aback by the report. He sees the unborn Dark Iron's claim to Ironforge as a new threat and intends to confer with Sylvanas and Cairne.",
        sources={V .. " #4004 completion"},related={"npc:thrall"}}
    local demon = {requires={"stratholme.commander_revealed"},
        body="The head of Balnazzar is proof that the Scarlet Crusade's Grand Crusader was a dreadlord, a brother of Varimathras. The discovery prompts an urgent report to Duke Nicholas Zverenhoff.",
        sources={V .. " #5262 description"},related={"npc:varimathras","npc:balnazzar"}}
    local doubt = {requires={"stratholme.report_delivered"},
        body="Zverenhoff asks whether the Crusade could have been controlled by the demon, unwittingly serving a greater evil. He raises the possibility rather than declaring the entire order's intentions proven.",
        sources={V .. " #5262 completion"}}
    local notes, quests = {}, {}
    notes["dungeon:blackrock-depths"] = Rule(
        "Blackrock Depths contains Shadowforge City, the Dark Iron capital within Blackrock Mountain. Emperor Dagran Thaurissan rules its people under the shadow of Ragnaros, whose elemental stronghold lies deeper below. Prisons, foundries, guarded streets and the Grim Guzzler tavern stand along the route toward the Imperial Seat.\n\nThe city is also the center of a dispute with Ironforge. King Magni seeks his daughter Moira and believes that Thaurissan has enchanted her. He calls for the emperor's death while insisting that she be spared.",
        V .. " #4362 description; #3801 Dark Iron Legacy", {"faction:dark-iron","npc:dagran","npc:moira"}, {family,husband})
    notes["npc:dagran"] = Rule(
        "Emperor Dagran Thaurissan rules the Dark Iron dwarves from the Imperial Seat in Blackrock Depths. His feud with King Magni Bronzebeard becomes a crisis for Ironforge when Magni's daughter Moira remains with the emperor. Magni believes that Dagran controls her through a spell and orders his death, insisting that Moira be spared even if she resists.",
        V .. " #4362 description", {"dungeon:blackrock-depths","npc:magni","npc:moira"}, {family,husband})
    notes["npc:moira"] = Rule(
        "Princess Moira Bronzebeard is King Magni's daughter. Her disappearance brings Ironforge's royal concerns into the conflict with the Dark Iron dwarves. Magni believes that Emperor Thaurissan has enchanted her in Blackrock Depths and seeks her return unharmed.",
        V .. " #4362 description", {"npc:magni","dungeon:blackrock-depths"}, {family,husband})
    notes["npc:magni"] = Rule(
        "King Magni Bronzebeard rules Ironforge, bearing the responsibilities of an Alliance monarch and the anguish of a father. His daughter Moira is with Emperor Dagran Thaurissan in Blackrock Depths. Magni believes his old Dark Iron enemy has enchanted her and calls for her return unharmed.\n\nHis concern for his subjects also appears in Sara Balloo's petition: her grief moves him to commission a memorial for her husband Sully, lost in the Alliance's service.",
        V .. " #4362 description; #683 and #686", {"npc:sara-balloo","faction:dark-iron"}, {family,husband,magniReply})
    notes["dungeon:stratholme"] = Rule(
        "Stratholme is the ruined northern city where Arthas ordered the slaughter of inhabitants he believed infected with the plague, breaking with Uther. Its streets now hold Scourge forces and a Scarlet Crusade bastion, enemies fighting amid the remains of Lordaeron.\n\nBaron Rivendare commands the undead stronghold, while the Scarlet Bastion answers to Grand Crusader Dathrohan. The Argent Dawn investigates the plague's unnatural potency and the power drawn from the city's ziggurats. Anthion Harmon's spirit begs for the rescue of his wife Ysida from Rivendare.",
        V .. " #5212, #5213, #8945 and #8968", {"npc:arthas","npc:rivendare","group:scarlet-crusade"}, {demon,doubt})
    notes["npc:balnazzar"] = Rule(
        "Balnazzar is the dreadlord discovered behind the Scarlet Crusade's Grand Crusader in Stratholme. His severed head supplies proof for the report to the Argent Dawn.",
        V .. " #5262 description", {"dungeon:stratholme","group:scarlet-crusade"}, {demon,doubt})
    -- Dathrohan and Balnazzar share one canonical ID. An alternate public title
    -- would disclose their equivalence when reached through the other alias.
    notes["npc:balnazzar"].visibleRequires={"stratholme.commander_revealed"}
    notes["group:scarlet-crusade"] = Rule(
        "The Scarlet Crusade is a human religious army formed amid Lordaeron's destruction by the Scourge. Its members claim the Holy Light's authority in a war to purge the undead from their homeland. The old Scarlet Monastery in Tirisfal has become one of its fortresses.\n\nRaleigh the Devout, a former member, describes innocent outsiders tortured as suspected plague carriers. The Crusade hunts Forsaken as well as Scourge, and living travelers can be condemned regardless of allegiance. Its forces extend through Hearthglen, Tyr's Hand and the Scarlet Bastion in Stratholme.",
        V .. " #1052, #1053, #6144 and #6145", {"dungeon:scarlet-monastery","npc:whitemane","dungeon:stratholme"}, {demon,doubt})
    -- Retain historical dreadlord lore without an edge identifying today's commander.
    local varimathras = A.GetLoreNote("npc:varimathras")
    if varimathras then
        notes["npc:varimathras"] = Rule(varimathras.body, varimathras.sources[1], {"npc:sylvanas","place:undercity"}, {demon})
        notes["npc:varimathras"].public.sources=varimathras.sources
    end
    for _,name in ipairs({"jarien","sothos"}) do
        notes["npc:"..name] = Rule(
            "Jarien and Sothos are warriors sought within the Scarlet Bastion of Stratholme. Reports say the Grand Crusader slew them after they failed initiation rites in his chamber.",
            V .. " #8968 and #8991 descriptions", {"dungeon:stratholme"}, {demon})
    end
    for _,title in ipairs({"The Royal Rescue","The Fate of the Kingdom","The Princess Saved?","The Princess's Surprise"}) do
        local blocks={family,husband}
        if title=="The Princess Saved?" then blocks={family,husband,thrallReply}
        elseif title=="The Princess's Surprise" then blocks={family,husband,magniReply} end
        quests[title]=Rule("The search for Princess Moira brings royal concerns into the struggle within Blackrock Depths. Ironforge's king and the Dark Iron emperor stand on opposing sides of the conflict.",
            V .. " #4003, #4004, #4362 and #4363", {"dungeon:blackrock-depths","npc:moira"},blocks)
    end
    quests["The Truth Comes Crashing Down"] = Rule(
        "The Argent Dawn seeks evidence about the forces commanding Stratholme. Duke Nicholas Zverenhoff receives reports from those who enter the ruined city.",
        V .. " #5262", {"dungeon:stratholme"}, {demon,doubt})
    A.RegisterLoreDiscovery({facts={
        ["moira.family"]={presented={4004,4363},completed={4004,4363}},
        ["moira.husband"]={presented={4004},completed={4004}},
        ["moira.magni_reply"]={completed={4363}},
        ["moira.thrall_reply"]={completed={4004}},
        ["stratholme.commander_revealed"]={presented={5262},completed={5262}},
        ["stratholme.report_delivered"]={completed={5262}},
    },notes=notes,quests=quests})
end

