        sources = {RoL, V .. " #97288 Unending Torment (description)"}, related = {"dungeon:lordaeron-ruins"}},
        blocks = {othmar}}
    A.RegisterLoreDiscovery({facts = {
        ["baron.othmar"] = {presented = {97289}, completed = {97289}},
    }, notes = notes})
end

